using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SlowCoffee.Infrastructure.Data; using SlowCoffee.Domain.Entities;
namespace SlowCoffee.Web.Controllers; public class RelatorioController(AppDbContext db):Controller { public async Task<IActionResult> Index(){ViewBag.TotalProdutos=await db.Produtos.CountAsync(x=>x.Ativo);ViewBag.TotalClientes=await db.Clientes.CountAsync(x=>x.Ativo);ViewBag.TotalPedidos=await db.Pedidos.CountAsync();ViewBag.Faturamento=await db.Pedidos.Where(x=>x.Status!=StatusPedido.Cancelado).SumAsync(x=>(decimal?)x.ValorTotal)??0;ViewBag.PedidosProntos=await db.Pedidos.CountAsync(x=>x.Status==StatusPedido.Pronto);return View();} }
